std::unique_ptr<Order> process_order(int id, double price) {
    auto o = std::make_unique<Order>(Order{id, price});
    validate(*o);   // if this throws, o's destructor still runs -- no leak
    enrich(*o);
    return o;        // ownership moved out, not copied
}

std::vector<double> simulate_prices(int n) {
    std::vector<double> prices;
    prices.reserve(n);
    for (int i = 0; i < n; ++i) prices.push_back(100.0 + 0.01 * i);
    return prices;   // moved (or elided), not copied
}
